class FilePilotRepository{
  constructor(file){this.file=path.resolve(file);this.state={calls:[],documents:[],notes:[],exports:[],pickupEstimates:[],settlements:[],workItems:[],archives:[],customers:[],vehicleLoad:[],cashEntries:[]};this.load()}
  load(){if(fs.existsSync(this.file)){const x=JSON.parse(fs.readFileSync(this.file,'utf8'));for(const k of Object.keys(this.state))if(!Array.isArray(x[k]))x[k]=[];this.state={...this.state,...x}}return this}
  save(){fs.mkdirSync(path.dirname(this.file),{recursive:true});const t=this.file+'.tmp';fs.writeFileSync(t,JSON.stringify(this.state,null,2));fs.renameSync(t,this.file)}
  list(org,key){this.load();return clone(this.state[key].filter(x=>x.organisationId===org))}
  add(key,row){this.load();this.state[key].push(clone(row));this.save();return clone(row)}
  upsert(org,key,row){this.load();const clean={...clone(row),organisationId:org},i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===clean.id);if(i>=0)this.state[key][i]=clean;else this.state[key].push(clean);this.save();return clone(clean)}
  replaceOrganisation(org,key,rows){this.load();this.state[key]=this.state[key].filter(v=>v.organisationId!==org).concat((rows||[]).map(v=>({...clone(v),organisationId:org})));this.save();return this.list(org,key)}
  update(org,key,id,patch){this.load();const i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===id);if(i<0)return null;this.state[key][i]={...this.state[key][i],...clone(patch)};this.save();return clone(this.state[key][i])}
  remove(org,key,id){this.load();const i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===id);if(i<0)return null;const [row]=this.state[key].splice(i,1);this.save();return clone(row)}
  removeWhere(org,key,field,value){this.load();const before=this.state[key].length;this.state[key]=this.state[key].filter(v=>!(v.organisationId===org&&v[field]===value));const removed=before-this.state[key].length;if(removed)this.save();return removed}
  find(org,key,id){this.load();const x=this.state[key].find(v=>v.organisationId===org&&v.id===id);return x?clone(x):null}
}
class MemoryPilotRepository{
  constructor(){this.state={calls:[],documents:[],notes:[],exports:[],pickupEstimates:[],settlements:[],workItems:[],archives:[],customers:[],vehicleLoad:[],cashEntries:[]}}
  list(org,key){return clone(this.state[key].filter(x=>x.organisationId===org))}
  add(key,row){this.state[key].push(clone(row));return clone(row)}
  upsert(org,key,row){const clean={...clone(row),organisationId:org},i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===clean.id);if(i>=0)this.state[key][i]=clean;else this.state[key].push(clean);return clone(clean)}
  replaceOrganisation(org,key,rows){this.state[key]=this.state[key].filter(v=>v.organisationId!==org).concat((rows||[]).map(v=>({...clone(v),organisationId:org})));return this.list(org,key)}
  update(org,key,id,patch){const i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===id);if(i<0)return null;this.state[key][i]={...this.state[key][i],...clone(patch)};return clone(this.state[key][i])}
  remove(org,key,id){const i=this.state[key].findIndex(v=>v.organisationId===org&&v.id===id);if(i<0)return null;const [row]=this.state[key].splice(i,1);return clone(row)}
  removeWhere(org,key,field,value){const before=this.state[key].length;this.state[key]=this.state[key].filter(v=>!(v.organisationId===org&&v[field]===value));return before-this.state[key].length}
  find(org,key,id){const x=this.state[key].find(v=>v.organisationId===org&&v.id===id);return x?clone(x):null}
}
class PilotDocumentStorage{
  constructor(root){this.root=path.resolve(root)}
  put({organisationId,id,fileName,mime,bytes}){const safe=String(fileName||'beleg').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,120);const body=Buffer.from(bytes);if(body.length>12*1024*1024)throw Object.assign(new Error('too large'),{code:'PAYLOAD_TOO_LARGE'});const dir=path.join(this.root,organisationId,id);fs.mkdirSync(dir,{recursive:true});const file=path.join(dir,safe);fs.writeFileSync(file,body);return {fileName:safe,mime,size:body.length,sha256:crypto.createHash('sha256').update(body).digest('hex'),objectKey:path.relative(this.root,file).split(path.sep).join('/')}}
  remove({organisationId,id}){const dir=path.join(this.root,organisationId,id);fs.rmSync(dir,{recursive:true,force:true});return true}
  read({organisationId,id,fileName}){const safe=String(fileName||'').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,120);const file=path.join(this.root,organisationId,id,safe);if(!fs.existsSync(file))throw Object.assign(new Error('not found'),{code:'NOT_FOUND'});return fs.readFileSync(file)}
  archiveExport({organisationId,archiveId,exportRow,documents,delivery,createdAt}){const dir=path.join(this.root,'_exports',organisationId,archiveId);if(fs.existsSync(dir))throw Object.assign(new Error('archive exists'),{code:'STATE_INVALID'});fs.mkdirSync(dir,{recursive:true});const files=[];documents.forEach((doc,index)=>{const original=this.read({organisationId,id:doc.id,fileName:doc.storage&&doc.storage.fileName}),safe=String(doc.storage&&doc.storage.fileName||'beleg').replace(/[^a-zA-Z0-9._-]/g,'_').slice(0,100),name=String(index+1).padStart(3,'0')+'-'+doc.id+'-'+safe,target=path.join(dir,name);fs.writeFileSync(target,original,{flag:'wx'});files.push({documentId:doc.id,fileName:name,originalFileName:doc.storage&&doc.storage.fileName||safe,mime:doc.storage&&doc.storage.mime||'application/octet-stream',size:original.length,sha256:crypto.createHash('sha256').update(original).digest('hex'),receiptCategory:doc.receiptCategory||null,expenseClass:doc.expenseClass||null,company:doc.company||'',date:doc.date||null,amount:doc.amount??null,businessAmount:doc.businessAmount??null})});const manifest={archiveId,organisationId,exportId:exportRow.id,month:exportRow.month,createdAt,documentIds:exportRow.documentIds.slice(),count:files.length,totalAmount:exportRow.totalAmount,delivery:{mode:delivery&&delivery.mode||null,accepted:delivery&&delivery.accepted===true,to:delivery&&delivery.to||null},files};const body=Buffer.from(JSON.stringify(manifest,null,2));fs.writeFileSync(path.join(dir,'manifest.json'),body,{flag:'wx'});return {archiveId,objectKey:path.relative(this.root,dir).split(path.sep).join('/'),manifestSha256:crypto.createHash('sha256').update(body).digest('hex'),fileCount:files.length}}
  readArchiveManifest({organisationId,archiveId}){const file=path.join(this.root,'_exports',organisationId,archiveId,'manifest.json');if(!fs.existsSync(file))throw Object.assign(new Error('not found'),{code:'NOT_FOUND'});return JSON.parse(fs.readFileSync(file,'utf8'))}
  readArchiveFile({organisationId,archiveId,fileName}){const safe=path.basename(String(fileName||''));const file=path.join(this.root,'_exports',organisationId,archiveId,safe);if(!fs.existsSync(file)||safe==='manifest.json')throw Object.assign(new Error('not found'),{code:'NOT_FOUND'});return fs.readFileSync(file)}
}

